from pathlib import Path
import html,json,re
r=Path(__file__).resolve().parent.parent
H=html.escape
P=lambda s:'<p>'+s+'</p>'
C=lambda s:'<code>'+H(s)+'</code>'
def code(s):return '<pre><code class="language-c">'+H(s)+'</code></pre>'
def table(head,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+H(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+H(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def steps(rows):return '<ol class="steps">'+''.join('<li>'+s+'</li>' for s in rows)+'</ol>'
def trace(tokens,cols=None,counts=False):
 stack=[];rows=[]
 for t in tokens.split():
  if t in '+-*/':
   b=stack.pop();a=stack.pop();v={'+':lambda:a+b,'-':lambda:a-b,'*':lambda:a*b,'/':lambda:a//b}[t]();stack.append(v);why=f'{a} {t} {b} = {v}를 계산해 다시 넣어요.';pu,po=1,2
  else:stack.append(int(t));why='숫자라서 그대로 넣어요.';pu,po=1,0
  if cols:row=[t]+stack+['—']*(cols-len(stack))+[why]
  else:row=[t,str(stack),why]
  if counts:row +=[pu,po]
  rows.append(row)
 head=['읽은 토큰']+([f'Stack[{i}]' for i in range(cols)] if cols else ['처리 후 스택'])+['이유']
 if counts:head+=['push','pop']
 return table(head,rows)
def stack_picture():return '<figure class="figure"><svg id="operand-order" viewBox="0 0 480 155" role="img" aria-label="스택 위의 오른쪽 피연산자를 먼저 꺼내고 아래의 왼쪽 피연산자를 나중에 꺼내요"><rect class="fig-ink" x="20" y="75" width="160" height="40"/><rect class="fig-accent" x="20" y="30" width="160" height="40"/><text class="fig-text" x="35" y="55">위: 오른쪽 피연산자</text><text class="fig-text" x="35" y="100">아래: 왼쪽 피연산자</text><path class="fig-accent" d="M185 50H260M252 44L260 50L252 56"/><text class="fig-text" x="273" y="55">먼저 꺼내요</text><path class="fig-ink" d="M185 95H260M252 89L260 95L252 101"/><text class="fig-text" x="273" y="100">나중에 꺼내요</text></svg><figcaption>스택 상태는 항상 왼쪽이 바닥, 오른쪽이 맨 위예요.</figcaption></figure>'
def postfix_recall(clue):return P(clue+'라는 단서에서 후위 표기(postfix)와 스택(stack)을 떠올려요. 스택은 마지막에 넣은 값을 먼저 꺼내는 후입선출(LIFO)이에요.')+P('피연산자(operand)는 계산할 숫자이고, 연산자(operator)는 +·−·*·/ 같은 계산 표시예요. 숫자는 push로 넣고, 이항 연산자는 오른쪽 값을 먼저 pop하고 왼쪽 값을 다음에 pop한 뒤 계산 결과를 다시 push해요.')+P('정상적인 이항 후위식에서는 연산자마다 값 두 개가 준비되어 있어야 하고, 마지막에는 결과 한 개가 남아요. 뺄셈·나눗셈은 '+C('왼쪽 값 op 오른쪽 값')+' 순서가 중요해요.')+stack_picture()
def emit(n,under,recall,start,solve,verify,pit,retry,summary):
 titles=['문제를 내 말로 읽기','이 문제를 봤을 때 떠올릴 개념과 공식','종이에 쓰는 첫 줄','왜 이렇게 푸는지 함께 따라가요','완성 답과 검산','이 문제에서 조심할 점','혼자 다시 풀어 보기'];keys=['understand','recall','start','solve','verify','pitfall','retry'];bs=[under,recall,start,solve,verify,pit,steps(retry)]
 for index in (3,4):
  if '<h5>' in bs[index]:bs[index]=''.join('<div class="part">'+part+'</div>' for part in re.split(r'(?=<h5>)',bs[index]) if part)
  bs[index]='<div data-subpart="main">'+bs[index]+'</div>'
 markup='\n'.join(f'<div class="layer {"eli5" if k=="understand" else "warn" if k=="pitfall" else "formal"}" data-explanation="{k}"><h4>{t}</h4>{b}</div>' for k,t,b in zip(keys,titles,bs))
 markup+='<div class="sum" hidden>'+''.join('<div class="summary-group"><h4>'+title+'</h4>'+P(text)+'</div>' for title,text in zip(['떠올릴 개념·공식','첫 줄','완성 답·검산'],summary))+'</div>'
 (r/'explanations'/f'p{n}.html').write_text(markup)
# P1
emit(1,P('계산 결과를 스택에 남긴 상태까지, 넣는 동작과 꺼내는 동작을 각각 세어요.'),postfix_recall('“후위표기법으로 바꾼 다음 스택으로 수식 계산”')+P('피연산자 수를 $n$, 이항 연산자 수를 $m$이라고 하면 $$N_{push}=n+m,\\qquad N_{pop}=2m$$예요. $N_{push}$·$N_{pop}$은 실행 횟수예요. 숫자마다 한 번 넣고, 연산자마다 두 번 꺼내 결과를 한 번 넣기 때문이에요. 변환 과정의 연산 횟수는 세지 않고 최종 결과도 꺼내지 않는 조건이에요.'),P(C('후위식: 5 6 * 4 2 / + 1 -'))+P('바로 아래에 '+C('숫자 5개, 연산자 4개')+'라고 적어요.'),P('곱셈·나눗셈을 먼저 처리하는 후위식이에요. 각 토큰을 읽고 상태와 횟수를 한 행씩 적어요.')+trace('5 6 * 4 2 / + 1 -',counts=True)+P('숫자를 넣은 5번과 중간 결과를 넣은 4번을 합치면 push는 9번이에요. 연산 4번마다 두 값을 꺼내므로 pop은 8번이에요.'),P('<strong>정답: push 9번, pop 8번.</strong> 결과 31은 스택에 남아요.')+P('독립 검산: 원래 식을 우선순위대로 계산하면 $5\\times6+4/2-1=30+2-1=31$이에요. 순원소 증가량도 $9-8=1$이므로 마지막 원소 한 개와 맞아요.'),P('최종 결과를 반환하려고 마지막 pop을 추가하면 9번이 되지만, 이 문제는 “최종 결과 값은 스택에 존재”한다고 했어요. 후위식으로 변환할 때의 별도 연산자 스택도 계산 횟수에 섞지 않아요. 원문의 “스태”는 “스택”을 뜻하는 표기예요.'),['후위식과 숫자·연산자 개수를 써요.','각 토큰의 push·pop 횟수를 세어요.','마지막 결과를 꺼내지 않았는지 확인해요.'],['숫자는 push 1번, 이항 연산자는 pop 2번과 push 1번이에요.','5 6 * 4 2 / + 1 -','push 9번·pop 8번, 31 한 개가 남아요.'])
# P2 conversion states
conv=[('(','[(]','없음','괄호 경계를 넣어요.'),('2','[(]','2','숫자를 바로 출력해요.'),('+','[(, +]','2','괄호 위에 +를 넣어요.'),('4','[(, +]','2 4','숫자를 출력해요.'),(')','[]','2 4 +','+를 출력하고 괄호를 버려요.'),('*','[*]','2 4 +','*를 보류해요.'),('7','[*]','2 4 + 7','숫자를 출력해요.'),('-','[-]','2 4 + 7 *','더 높은 *를 먼저 출력해요.'),('6','[-]','2 4 + 7 * 6','숫자를 출력해요.'),('*','[-, *]','2 4 + 7 * 6','더 높은 *는 스택에 넣어요.'),('3','[-, *]','2 4 + 7 * 6 3','숫자를 출력해요.'),('+','[+]','2 4 + 7 * 6 3 * -','*를 출력하고 +와 같은 우선순위의 -도 먼저 출력해요.'),('1','[+]','2 4 + 7 * 6 3 * - 1','숫자를 출력해요.'),('끝','[]','2 4 + 7 * 6 3 * - 1 +','남은 +를 출력해요.')]
emit(2,P('(1)은 중위식을 후위식으로 바꿔요. (2)는 표에 이미 주어진 다른 후위식을 계산해요. 두 답을 따로 적어요.'),P('“postfix 표현으로 바꾸시오”라는 (1)의 단서는 <strong>연산자 스택</strong>을, “계산 과정의 테이블”이라는 (2)의 단서는 <strong>숫자 스택</strong>을 고르게 해요.')+P('(1) 중위(infix)는 연산자가 두 피연산자 사이에 있는 표기예요. 피연산자는 바로 출력하고 연산자를 잠시 스택에 둬요. 새 연산자보다 높은 우선순위 또는 같은 우선순위의 기존 연산자는 먼저 출력해요. +·−·*·/는 왼쪽 결합이므로 같은 우선순위도 먼저 나온 것을 처리해요. 괄호 안을 먼저 처리하고 괄호 자체는 출력하지 않아요.')+postfix_recall('(2)의 “postfix 형태의 식을 stack으로 계산”'),P('(1) '+C('연산자 스택 [], 출력 없음')+'으로 시작해요. 첫 글자는 (이므로 스택에 넣어요.')+P('(2) '+C('토큰 5 / Stack[0]=5')+'를 표의 첫 행에 적어요.'),'<h5>(1) 중위식 변환</h5>'+table(['읽은 것','연산자 스택','현재 출력','이유'],conv)+P('완성 후위식은 '+C('2 4 + 7 * 6 3 * - 1 +')+'예요.')+'<h5>(2) 별도로 주어진 후위식 계산</h5>'+P('입력은 '+C('5 6 * 4 2 / + 1 -')+'예요. 첫 번째 식의 숫자와 바꿔 쓰지 않아요. —는 유효한 원소가 없는 칸이에요.')+trace('5 6 * 4 2 / + 1 -',6),'<h5>(1) 완성 답과 검산</h5>'+P('<strong>답: '+C('2 4 + 7 * 6 3 * - 1 +')+'</strong>예요. 변환 결과를 독립 계산하면 '+C('6 * 7 - 18 + 1 = 25')+'이고 원래 중위식 '+C('(2+4)*7-6*3+1')+'의 25와 같아요.')+'<h5>(2) 완성 답과 검산</h5>'+P('<strong>답: 마지막 Stack[0]=31</strong>이에요. 위 표의 나머지 칸은 유효 원소가 없어요. 별도 식 '+C('5*6+4/2-1 = 31')+'과 일치해요.'),P('(1)의 식을 계산한 25를 (2)의 표 답으로 적으면 틀려요. 원자료가 서로 다른 식을 줬어요. 변환 스택에는 연산자를, 계산 스택에는 숫자와 중간 결과를 넣어요.'),['(1) 연산자 스택과 출력 두 칸을 그려 변환해요.','(2) 주어진 표의 토큰으로만 숫자 스택을 추적해요.','25와 31이 서로 다른 식의 값인지 확인해요.'],['변환은 연산자 스택, 계산은 피연산자 스택을 써요.','(1) 스택 []·출력 없음 / (2) 첫 행 5→[5]','(1) 2 4 + 7 * 6 3 * - 1 + / (2) 31'])
