emit(3,P('왼쪽부터 하나씩 읽고, 읽은 직후 스택에 남는 숫자를 표에 적어요.'),postfix_recall('“postfix 수식”과 “Stack[0]…Stack[3]”')+P('Stack[0]은 바닥 원소이고 마지막 사용 칸이 top이에요. 표에는 그 시점의 유효 원소만 적어요. pop 후 배열에 옛 비트값이 남아도 스택 원소로 세지 않아요.'),P(C('Token=7, Stack[0]=7, 나머지는 빈칸'))+P('두 번째 토큰 6은 그 위인 Stack[1]에 적을 준비를 해요.'),trace('7 6 2 / - 5 4 * +',4)+P('나눗셈은 먼저 나온 6을 나중에 나온 2로 나눠요. 그 결과 3을 꺼내 7에서 빼므로 4가 돼요. 그 뒤 5와 4를 곱한 20을 기존 4에 더해요.'),P('<strong>정답: 표의 상태는 [7], [7,6], [7,6,2], [7,3], [4], [4,5], [4,5,4], [4,20], [24]예요.</strong> 마지막 Stack[0]은 24이고 나머지는 비어요.')+P('독립 계산: $7-6/2+5\\times4=7-3+20=24$예요. 숫자 5개와 연산자 4개의 정상 후위식이므로 최종 값도 한 개예요.'),P('스택의 맨 위 2를 먼저 꺼낸다고 '+C('2 / 6')+'으로 계산하지 않아요. 첫 pop은 오른쪽 피연산자예요. 원문의 긴 대시 –는 뺄셈 기호로 읽어요.'),['한 토큰마다 한 행을 적어요.','나눗셈·뺄셈의 왼쪽과 오른쪽 값을 확인해요.','마지막 24 하나만 유효한지 확인해요.'],['후위식 계산에서 첫 pop은 오른쪽 피연산자예요.','7을 읽으면 Stack[0]=7이에요.','6/2=3, 7−3=4, 4+20=24예요.'])
