emit(4,P('열린 괄호를 기억했다가 알맞은 닫는 괄호와 짝지을 도구를 골라요.'),P('“괄호 검사”라는 단서에서 <strong>가장 최근에 열린 괄호부터 닫는다</strong>는 포함 관계를 떠올려요. 그래서 후입선출(LIFO: Last-In First-Out)인 스택(stack)이 맞아요.')+P('push는 열린 괄호를 기억하는 동작이고, pop은 가장 최근 괄호를 꺼내 짝을 비교하는 동작이에요. 닫는 괄호에서 비어 있거나 종류가 다르면 실패, 문자열 끝에 열린 괄호가 남아도 실패예요. 모든 비교가 맞고 끝에 비면 성공이에요.'),P(C('최근에 연 괄호를 먼저 꺼내야 한다 → 스택'))+P('이 이유를 적은 뒤 답칸에 자료구조 이름을 써요.'),steps(['열린 괄호를 만날 때마다 스택에 넣어요.','닫는 괄호를 읽으면 맨 위의 여는 괄호와 비교해요.','가장 늦게 넣은 괄호를 먼저 꺼내는 순서이므로 답은 스택이에요.']),P('<strong>정답: 스택.</strong> 정의와 검사 규칙을 대조하면 최근 열린 괄호를 먼저 꺼내는 동작이 항상 필요해요.')+P('작은 예시 '+C('([])')+'에서 (를 넣고 [를 넣어요. ]는 [와, )는 (와 짝이 맞아요. 큐처럼 (부터 꺼내면 ]와 맞지 않아요. 이 예시는 위 규칙의 확인이며, 선택 이유는 포함 관계 자체예요.'),P('좌우 괄호 수만 같다고 성공은 아니에요. '+C('([)]')+'는 종류의 포함 관계가 어긋나요. 최근 열린 괄호와 비교해야 해요.'),['괄호를 닫는 순서를 한 문장으로 적어요.','LIFO와 연결해 답 스택을 써요.'],['중첩된 괄호는 가장 최근에 연 것을 먼저 닫아요.','최근 괄호를 먼저 꺼내므로 스택이에요.','정답 스택. 개수·종류·포함 관계를 함께 확인해요.'])
