emit(5,P('계산할 숫자를 잠깐 보관했다가 바로 앞의 값부터 꺼낼 도구를 골라요.'),postfix_recall('“후위 표기식의 계산”'),P(C('연산자 앞에서 가장 최근 값 두 개를 꺼낸다 → 스택')),steps(['숫자는 스택에 넣어 기다리게 해요.','연산자를 읽을 때 최근 결과 두 개를 꺼내요.','계산 결과를 다시 넣어 다음 연산의 피연산자로 써요. 따라서 답은 스택이에요.']),P('<strong>정답: 스택.</strong> 후위식은 각 연산자의 바로 앞에 완성된 두 피연산자가 놓이는 구조라, 최근 값을 먼저 꺼내는 LIFO 규칙이 맞아요.')+P('확인 예시 '+C('2 3 + 4 *')+'에서 '+C('[2] → [2,3] → [5] → [5,4] → [20]')+'이 돼요. 계산한 5도 새로운 피연산자가 되어 스택에 다시 들어가요.'),P('숫자만 넣고 중간 결과를 넣지 않으면 다음 연산이 불가능해요. 이 계산에서는 연산자는 실행 신호이며 숫자 스택에 저장하는 값이 아니에요.'),['숫자·연산자를 만났을 때의 동작을 말해요.','계산 결과를 다시 넣는 이유를 설명해요.'],['후위식은 최근 피연산자 둘을 먼저 사용해요.','최근 값을 꺼내는 도구는 스택이에요.','정답 스택. 결과도 다시 넣어요.'])
# P6 blanks only
push="s->top = s->top + 1;\ns->stack[s->top] = item;"
pop="item = s->stack[s->top];\ns->top = s->top - 1;\nreturn item;"
loop="if (str[i] == '+') {\n    op1 = pop(&s);\n    op2 = pop(&s);\n    push(&s, op1 + op2);\n} else if (str[i] == '*') {\n    op1 = pop(&s);\n    op2 = pop(&s);\n    push(&s, op1 * op2);\n} else {\n    push(&s, str[i] - '0');\n}"
(r/'evidence/blank_answers.json').write_text(json.dumps(dict(push=push,pop=pop,loop=loop),ensure_ascii=False,indent=2))
emit(6,P('push·pop의 빈칸과 후위식을 읽는 반복문을 각각 채워요. 주어진 선언과 오류 분기는 그대로 두고 빈칸에 들어갈 문장만 써요.'),P('“top”, “push”, “pop”이라는 단서에서 배열 스택의 상태를 떠올려요. top은 마지막 유효 원소의 인덱스이고 -1은 빈 상태예요. push는 top을 먼저 증가시키고 저장하며, pop은 현재 값을 보관한 뒤 top을 감소시켜 반환해요.')+P('“한 자리 숫자(0~9), +와 *, 공백 없이”라는 조건은 각 문자 하나가 숫자 또는 연산자라는 뜻이에요. '+C("str[i] - '0'")+'은 숫자 문자를 정수로 바꿔요. 덧셈·곱셈은 두 값을 꺼내 계산하고 다시 넣어요. 이미 선언된 op1·op2를 사용하므로 새 변수 선언은 필요 없어요.')+P('<strong>실행 가정:</strong> 입력은 정상적인 후위식이며 길이는 99자 이하여야 해요. 연산자 앞에 값이 두 개 이상 있고, 스택 용량을 넘지 않으며, 정수 계산 결과가 C의 int 범위 안에 있어야 해요. 원문은 이런 잘못된 입력을 모두 막는 코드가 아니에요.'),P('push의 첫 줄은 '+C('s->top = s->top + 1;')+'이에요. pop의 첫 줄은 '+C('item = s->stack[s->top];')+'이에요. 반복문에서는 먼저 현재 문자가 +인지 검사해요.'),'<h5>① push의 else 빈칸</h5>'+code(push)+P('top이 -1이라면 먼저 0으로 올려야 첫 배열 칸에 저장할 수 있어요. 기존 top에 저장하면 맨 위 값을 덮어써요.')+'<h5>② pop의 else 빈칸</h5>'+code(pop)+P('top을 줄이기 전에 현재 값을 item에 보관해요. 그 뒤 top을 내리고 보관한 값을 돌려줘요.')+'<h5>③ main의 for문 빈칸</h5>'+code(loop)+P('op1은 먼저 꺼낸 오른쪽 값, op2는 다음에 꺼낸 왼쪽 값이에요. 여기서는 +·*만 있으므로 순서를 바꿔도 계산값은 같아요. 숫자 분기는 문자와 '+C("'0'")+'의 차이를 push해요. '+C('op')+'라는 변수를 추가하지 않고 원래 빈칸 안에서 해결했어요.'),P('<strong>완성 답은 위 세 코드 블록이에요.</strong> 원문에 빈칸 답만 삽입해 C11로 컴파일하고, 정상 입력을 실행했어요. 공백 오류 종료나 scanf의 폭 제한을 추가하지 않았어요.')+table(['입력','손으로 계산','실제 출력'],[['23+4*','(2+3)*4=20','result:20'],['52*3+','5*2+3=13','result:13'],['0','0','result:0'],['99*9+','9*9+9=90','result:90']])+P('검산에서는 모든 정상 입력이 같은 결과를 냈어요. 배열 원소 개수는 '+C('top+1')+'이고, 정상 push 뒤 1 늘며 정상 pop 뒤 1 줄어드는 불변식도 확인했어요. 여기서는 마지막 '+C('printf')+'가 결과를 pop하므로 실행 뒤 스택이 비어요.'),P('원문의 pop은 빈 스택 분기에서 값을 반환하지 않아요. 반환값을 사용하는 공백 pop은 정의된 정상 답으로 취급할 수 없고, 실제 컴파일에도 이 경로의 경고가 나와요. 무제한 '+C('scanf("%s", str)')+'도 긴 입력에 안전하지 않아요. 따라서 검산 결과는 위 실행 가정을 만족하는 입력에 한정해요. 원 코드는 고치지 않았어요.'),['top이 -1일 때 push의 두 줄을 추적해요.','현재 값을 먼저 보관하고 top을 내리는 pop을 써요.','23+4*의 각 문자와 스택 상태를 확인해요.'],['배열 스택의 top은 맨 위 인덱스예요. 한 자리 문자는 0 문자를 빼요.','push: top 증가 / pop: 현재 값 보관 / main: 문자 분기','빈칸만 채운 원문 코드로 정상 입력 4개 검산. 잘못된 입력은 보장하지 않아요.'])
# P7
emit(7,P('은행 고객이 들어온 순서대로 서비스를 받도록 대기열을 표현할 도구를 골라요.'),P('“은행창구”, “고객들이 들어오고 나감”이라는 단서는 <strong>먼저 온 고객을 먼저 처리하는 대기열</strong>을 떠올리게 해요. 선입선출(FIFO: First-In First-Out)을 따르는 큐(queue)가 맞아요.')+P('enqueue는 뒤(rear)에 새 고객을 넣고, dequeue는 앞(front)의 고객을 꺼내요. 시뮬레이션(simulation)은 실제 대기와 처리를 소프트웨어로 모델링하는 일이에요. 이 문항은 우선순위나 VIP 조건 없이 보통의 도착 순서를 유지하는 상황이에요.'),P(C('먼저 도착한 고객 → 먼저 서비스 → FIFO → 큐')),steps(['새 고객은 기존 고객 뒤에 줄을 서요.','창구는 맨 앞 고객부터 처리해요.','뒤 삽입·앞 삭제로 순서를 지키는 큐를 선택해요.']),P('<strong>정답: 큐.</strong> 정의와 현실 규칙을 비교하면 뒤에 합류한 고객이 기존 고객을 추월하지 않는 FIFO 순서가 일치해요.')+table(['사건','처리 후 대기열'],[['A 도착','[A]'],['B 도착','[A, B]'],['서비스 한 명','[B], A가 먼저 나감']])+P('어떤 고객 순서에서도 뒤에 넣고 앞에서 꺼내면 먼저 기다린 고객부터 처리해요. 표는 그 규칙을 확인하는 작은 사례예요.'),P('늦게 온 고객을 먼저 처리하는 스택은 보통의 은행 대기 순서를 뒤집어요. 문제에 없는 우선순위 조건을 추가해서 다른 자료구조를 고르지 않아요.'),['고객의 삽입 위치와 삭제 위치를 적어요.','FIFO를 한글로 풀어 말하고 큐를 써요.'],['은행 대기열은 먼저 온 고객부터 처리해요.','먼저 도착 → 먼저 서비스 → FIFO','정답 큐. 뒤에 넣고 앞에서 꺼내요.'])
# P8
emit(8,P('문장 속 자료구조의 순서와 쓰임이 모두 맞는지 따로 확인한 뒤, 전체 문장의 참·거짓을 판단해요.'),P('“선입선출(First-In First-Out)”과 “스택(Stack)”이 함께 나오는 것이 점검할 단서예요. 스택은 후입선출(LIFO), 큐는 선입선출(FIFO)이에요.')+P('문장이 “A 특징을 가진 B는 C에 쓰인다”라고 하면 특징과 사용 예가 모두 맞아야 참이에요. 스택을 괄호 검사에 쓰는 설명은 맞지만, 스택의 순서를 FIFO라고 부른 부분이 틀리면 전체는 거짓이에요.'),P(C('스택 = LIFO, FIFO가 아님'))+P('그다음 '+C('괄호 검사에 스택 사용 = 맞음')+'을 별도 줄에 써요.'),steps(['“선입선출의 특징을 가지는 스택”을 확인해요. 스택의 실제 특징은 후입선출이라 이 부분은 틀려요.','“스택은 괄호 검사에 이용될 수 있다”는 최근 열린 괄호부터 비교하므로 맞아요.','앞부분의 잘못된 특징 때문에 전체 문장은 거짓, X예요.']),P('<strong>정답: X.</strong> A를 넣고 B를 넣은 스택에서 한 번 pop하면 B가 먼저 나와요. 선입선출이면 A가 먼저 나와야 하므로 실제 스택 동작이 문장의 특징에 대한 반례예요.')+P('사용 예가 맞다는 사실은 잘못된 특징을 참으로 바꾸지 못해요. 이 문항은 틀린 문장을 판별하는 OX 문제라 원문을 LIFO로 고쳐 읽지 않아요.'),P('“괄호 검사”라는 익숙한 표현만 보고 O를 고르기 쉬워요. 특징과 응용을 따로 판정해요.'),['FIFO와 LIFO의 뜻을 적어요.','문장의 특징과 응용을 따로 판정해요.','틀린 부분을 짚고 X를 써요.'],['스택은 LIFO, 큐는 FIFO예요.','스택 = LIFO, 괄호 검사 사용은 맞음','정답 X. B가 먼저 나오는 동작이 FIFO 주장에 대한 반례예요.'])
